const root = path.resolve(import.meta.dirname, "..", "messages");

for (const locale of locales) {
  const dir = path.join(root, locale);
  await mkdir(dir, { recursive: true });
  for (const [namespace, byLocale] of Object.entries(messages)) {
    const content = byLocale[locale];
    if (!content) throw new Error(`Missing ${namespace}.${locale}`);
    await writeFile(
      path.join(dir, `${namespace}.json`),
      JSON.stringify(content, null, 2) + "\n",
      "utf8",
    );
  }
}

console.log(`Wrote messages for ${locales.length} locales × ${Object.keys(messages).length} namespaces.`);
